import base64, hashlib, json, re, sys
sys.path.insert(0, '/home/drx/MIPStarRE-qpbt/local/bin')
import gh_common
sha = '360402fdf4a39399f94331452d6e5d0a35c144be'
files = ['lean-toolchain', 'lakefile.toml', 'lake-manifest.json', 'comparator.json', 'verify.sh', '.github/workflows/comparator.yml']
out = {}
for path in files:
    row = gh_common.api(f'contents/{path}?ref={sha}')
    raw = base64.b64decode(row['content'])
    text = raw.decode('utf-8')
    out[path] = {'blob_sha': row['sha'], 'sha256': hashlib.sha256(raw).hexdigest()}
    if path == 'lean-toolchain':
        out[path]['value'] = text.strip()
    elif path == 'lakefile.toml':
        out[path]['mipstarre_rev'] = re.search(r'rev\\s*=\\s*\"([0-9a-f]{40})\"', text).group(1)
    elif path == 'lake-manifest.json':
        data = json.loads(text)
        pkg = next(p for p in data['packages'] if p['name'] == 'MIPStarRE')
        out[path]['rev'] = pkg['rev']
        out[path]['inputRev'] = pkg['inputRev']
    elif path == 'comparator.json':
        out[path]['config'] = json.loads(text)
    elif path == 'verify.sh':
        for key in ('COMPARATOR_REV', 'LANDRUN_REV', 'NANODA_REV'):
            m = re.search(rf'"'^{key}=([''^'"\\n]+)"'$'"', text, re.M)
            out[path][key] = m.group(1).strip('\"') if m else None
        out[path]['fake_landrun_branch_present'] = '--fake-landrun' in text
    elif path.endswith('comparator.yml'):
        out[path]['runs_verify_without_fake'] = bool(re.search(r'run:\\s*\\./verify\\.sh\\s*"'$'"', text, re.M))
print(json.dumps({'head': sha, 'files': out}, indent=2, sort_keys=True))
PY"

